<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
$root=dirname(__DIR__);$errors=[];$warnings=[];
if(PHP_VERSION_ID<80200)$errors[]='Требуется PHP 8.2+';if(PHP_INT_SIZE<8)$errors[]='Требуется 64-битный PHP';
foreach(['pdo_mysql','mbstring','openssl','curl','dom','zip','fileinfo'] as $extension)if(!extension_loaded($extension))$errors[]='Не найдено расширение '.$extension;
if(!is_file($root.'/app/config.php')&&!getenv('PINA_CONFIG'))$errors[]='Не настроен app/config.php';
if(!$errors){require $root.'/app/bootstrap.php';require $root.'/app/giftcards.php';require $root.'/app/giftcards-documents.php';try{db()->query('SELECT 1');foreach(['001-giftcards'=>'giftcards.sql','002-merchant-credentials'=>'giftcards-credentials.sql','003-operations'=>'giftcards-operations.sql','004-access-audit'=>'giftcards-access-audit.sql','005-program-controls'=>'giftcards-program-controls.sql'] as $v=>$sql){$r=one('SELECT checksum FROM pg_schema_migrations WHERE version=?',[$v]);if(!$r||!hash_equals($r['checksum'],hash_file('sha256',$root.'/database/'.$sql)))$errors[]='Миграция '.$v.' отсутствует или отличается от исходной';}gc_key();gc_storage();$g=gc_settings();$pina=gc_credentials('pina');if(empty($pina['api_key'])||empty($pina['site_id']))$warnings[]='Ключ Pina Market ещё не задан';if(!gc_signature_config())$warnings[]='Подпись не добавлена: договоры формируются как проекты';if(!($g['legal_approved']??false))$warnings[]='Оферта и инструкция банка ещё не утверждены';if(($g['balance_return_mode']??'unconfirmed')==='unconfirmed')$warnings[]='Метод возврата учётного остатка не согласован';if(!one("SELECT id FROM pg_issuers WHERE status='active' AND contract_status='approved'"))$warnings[]='Нет подключённых эмитентов: каталог будет пуст';if(($g['sales_enabled']??false)&&$warnings)$errors[]='При открытых продажах остались незавершённые настройки';}catch(Throwable $e){$errors[]='Ошибка проверки базы или приватных настроек: '.$e->getMessage();}}
foreach(['dist/giftcards/index.html','app/giftcards-assets.json','app/giftcards-shell.html','app/giftcards-template.docx','app/giftcards-offer.json'] as $f)if(!is_file($root.'/'.$f))$errors[]='Не найден файл '.$f;
foreach($warnings as $w)echo 'ОЖИДАЕТ НАСТРОЙКИ: '.$w."\n";foreach($errors as $e)fwrite(STDERR,'ОШИБКА: '.$e."\n");if(!$errors)echo "Структура пакета и доступные настройки проверены. Это не подтверждение реальных операций банка или V-DAR.\n";exit($errors?1:0);
